package com.example.statusdrafter.entity;
import jakarta.persistence.*; import java.time.*;
@Entity @Table(name="status_history") public class StatusHistory { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(optional=false,fetch=FetchType.LAZY) @JoinColumn(name="task_id") private Task task; @ManyToOne(optional=false,fetch=FetchType.LAZY) @JoinColumn(name="employee_id") private User employee; @Enumerated(EnumType.STRING) private Task.Status oldStatus; @Enumerated(EnumType.STRING) private Task.Status newStatus; @Column(columnDefinition="TEXT") private String note; @Column(nullable=false) private LocalDateTime changedAt;
 public StatusHistory(){} public StatusHistory(Task t,User e,Task.Status o,Task.Status n,String note){task=t;employee=e;oldStatus=o;newStatus=n;this.note=note;changedAt=LocalDateTime.now();} public Long getId(){return id;} public Task getTask(){return task;} public User getEmployee(){return employee;} public Task.Status getOldStatus(){return oldStatus;} public Task.Status getNewStatus(){return newStatus;} public String getNote(){return note;} public LocalDateTime getChangedAt(){return changedAt;} }
